17_004\') then 0 else o.abs_Tax_exclusive_gross end as abs_Tax_exclusive_gross, case when o.Reference_Code = \'RD1_FR_CN_YFLHOME100000011100\' then 457.48 when o.Reference_Code = \'RD_PSP_YFLHOME100000011992\' then 84 when o.Reference_Code in (\'Zepto_3100735236_001\', \'Zepto_3100735236_002\', \'Zepto_3100748517_004\') then 0 else o.Total_tax_amount end as Total_tax_amount, o.Shipping_charge, o.Promotion_discount, o.payment_mode, o.Suborder_No from ( select \'Easyecom YFL sale\' as report_type, case when trim(UPPER(\"Company Name\")) in (\'YOUR FOOD LAB (MUM)\', \'SEVEN CHEF MUM\', \'SEVEN CHEF RAI\') then \'YFL MUM\' when trim(upper(\"Company Name\")) in (\'YOUR FOOD LAB (BLR)\', \'SEVEN CHEF BLR\') then \'YFL BLR\' when trim(upper(\"Company Name\")) in (\'YOUR FOOD LAB (GGN)\', \'YOUR FOOD LAB\', \'SEVEN CHEF GGN\') then \'YFL GGN\' else trim(upper(\"Company Name\")) end as Company_Name, \"Seller GST Num\" as seller_gst, \"MP Name\", \'YFL\' as brand, coalesce(c.NEW_MP_NAME, Case when lower(\"Reference Code\") like any (\'%b2bsc%\') and lower(\"MP Name\") in (\'b2b\', \'offline\', \'retail customers\') and not(lower(\"Reference Code\") like any (\'%sample%\',\'%_foc_%\')) then upper(\"MP Name\")||\'_SALE\' when lower(\"MP Name\") = \'amazon.in\' then \'Amazon EasyShip EE\' when lower(\"MP Name\") = \'shopify\' and lower(\"Order Type\") = \'b2b\' then \'SHOPIFY\' when lower(\"Reference Code\") in (\'fba15jpmw9r1\', \'fba15jpmw9r1_or2\') then (upper(\"MP Name\") || \'_stn\') when lower(\"Reference Code\") like \'rez%\' then \'RetailEZ\' when lower(\"Reference Code\") like any (\'rd_sp_%\', \'rd1_sp_%\', \'rd2_sp_%\', \'rd3_sp_%\', \'rd4_sp_%\', \'rd5_sp_%\', \'rd6_sp_%\') then \'Redispatch_cogs\' when lower(\"Reference Code\") like any (\'rd_fr_cn%\', \'rd1_fr_cn%\', \'rd2_fr_cn%\', \'rd3_fr_cn%\', \'rd4_fr_cn%\', \'rd5_fr_cn%\', \'rd6_fr_cn%\') then \'Shopify Manual\' when lower(\"Reference Code\") like any (\'%yflh_cod%\', \'yflh_pp_%\') then \'Shopify Manual\' w