x)\" as float) as Shipping_charge, try_cast(\"Promotion Discount(Excluding Tax)\" as float) as Promotion_discount, \"Payment Mode\" as payment_mode, \"Suborder No\" as Suborder_No from HOX_DB.MAPLEMONK.easyecom_hox_7chefs_tax_returns a left join ( select * from HOX_DB.MAPLEMONK.stock_transfer_customers where 1=1 Qualify row_number() over(partition by lower(STN_CUSTOMER_NAME) order by 1) = 1 )b on lower(a.\"MP Name\") = lower(b.STN_CUSTOMER_NAME) left join (select * from (select * , row_number() over (partition by lower(customer_name) order by 1) rw from HOX_DB.MapleMonk.b2b_customer_mapping ) where rw=1 ) B2B on lower(a.\"MP Name\") = lower(B2B.customer_name) left join HOX_DB.MAPLEMONK.order_details_changes c on lower(a.\"Reference Code\") = lower(c.REFERENCE_CODE) where lower(a.\"Reference Code\") not like \'%test%\' )as o where o.Reference_Code not in (\'YFLHOME100000013283_REROUTED_3319568\', \'YFLHOME100000013747_REROUTED_1253490\', \'YFLHOME100000013748_REROUTED_5916633\', \'YFLHOME100000013753_REROUTED_3456749\', \'YFLHOME100000013754_REROUTED_6132319\', \'YFLHOME100000013755_REROUTED_9072679\', \'YFLHOME100000013759_REROUTED_8716623\', \'YFLHOME100000013760_REROUTED_1757687\', \'YFLHOME100000013765_REROUTED_4376566\', \'YFLHOME100000013770_REROUTED_3496129\', \'YFLHOME100000013771_REROUTED_1458117\')",
